export { Slider } from "./slider";
export {
  useSlider,
  type SliderOrientation,
  type SliderProps,
  type SliderValue,
  type UseSliderReturn,
} from "./useSlider";

import { cc } from "sinwan/component";
import { cn } from "@/lib/utils";
import { useSlider, type SliderProps } from "./useSlider";

const Slider = cc<SliderProps>((props) => {
  const slider = useSlider(props);

  return (
    <div
      data-slot="slider"
      data-orientation={slider.orientation.value}
      data-disabled={props.disabled ? "" : undefined}
      class={cn(
        "relative flex w-full touch-none items-center select-none data-disabled:opacity-50 data-vertical:h-full data-vertical:min-h-40 data-vertical:w-auto data-vertical:flex-col",
        slider.orientation.value === "vertical" &&
          "h-full min-h-40 w-auto flex-col",
        props.disabled && "opacity-50",
        props.class,
      )}
    >
      <div
        data-slot="slider-track"
        class={cn(
          "relative grow overflow-hidden rounded-full bg-muted",
          slider.orientation.value === "vertical" ? "h-full w-1" : "h-1 w-full",
        )}
      >
        <div
          data-slot="slider-range"
          class={cn(
            "absolute bg-primary select-none",
            slider.orientation.value === "vertical"
              ? "w-full bottom-0"
              : "h-full left-0",
          )}
          style={slider.orientation.value === "vertical"
              ? `height: ${slider.percent.value}%`
              : `width: ${slider.percent.value}%`
          }
        />
      </div>
      <input
        type="range"
        data-slot="slider-input"
        id={props.id}
        name={props.name}
        min={String(slider.min.value)}
        max={String(slider.max.value)}
        step={String(slider.step.value)}
        disabled={props.disabled}
        aria-orientation={slider.orientation.value}
        value={String(slider.primary.value)}
        class={cn(
          "absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0 disabled:pointer-events-none disabled:cursor-not-allowed",
          slider.orientation.value === "vertical" &&
            "[writing-mode:vertical-lr]",
        )}
        oninput={(event) => {
          const target = event.currentTarget as HTMLInputElement;
          slider.commit(Number(target.value));
        }}
      />
      <span
        data-slot="slider-thumb"
        aria-hidden="true"
        class="pointer-events-none absolute z-0 size-3 shrink-0 rounded-full border border-ring bg-white ring-ring/50 transition-[color,box-shadow] select-none after:absolute after:-inset-2"
        style={slider.orientation.value === "vertical"
            ? `left: 50%; bottom: ${slider.percent.value}%; transform: translate(-50%, 50%)`
            : `top: 50%; left: ${slider.percent.value}%; transform: translate(-50%, -50%)`
        }
      />
    </div>
  );
});

export { Slider };

import {
  computed,
  signal,
  type Computed,
  type Signal,
} from "sinwan/reactivity";

export type SliderValue = number | number[];

export type SliderOrientation = "horizontal" | "vertical";

export type SliderProps = {
  class?: string;
  defaultValue?: SliderValue;
  value?: SliderValue;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  orientation?: SliderOrientation;
  onValueChange?: (value: number[]) => void;
  id?: string;
  name?: string;
};

export type UseSliderReturn = {
  min: Computed<number>;
  max: Computed<number>;
  step: Computed<number>;
  orientation: Computed<SliderOrientation>;
  values: Signal<number[]> | Computed<number[]>;
  primary: Computed<number>;
  percent: Computed<number>;
  commit: (next: number) => void;
};

function toValues(
  value: SliderValue | undefined,
  fallback: SliderValue | undefined,
  min: number,
): number[] {
  const source = value ?? fallback;
  if (Array.isArray(source) && source.length > 0) {
    return source.map((n) => Number(n));
  }
  if (typeof source === "number") return [source];
  return [min];
}

function sameValues(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

function snapValue(
  next: number,
  min: number,
  max: number,
  step: number,
): number {
  if (!(step > 0)) {
    return Math.min(max, Math.max(min, next));
  }
  const snapped = Math.round((next - min) / step) * step + min;
  const decimals = String(step).includes(".")
    ? (String(step).split(".")[1]?.length ?? 0)
    : 0;
  const rounded =
    decimals > 0 ? Number(snapped.toFixed(decimals)) : snapped;
  return Math.min(max, Math.max(min, rounded));
}

export function useSlider(props: SliderProps): UseSliderReturn {
  const min = computed(() => props.min ?? 0);
  const max = computed(() => props.max ?? 100);
  const step = computed(() => props.step ?? 1);
  const orientation = computed<SliderOrientation>(
    () => props.orientation ?? "horizontal",
  );
  const valuesLocal = signal(
    toValues(undefined, props.defaultValue, min.value),
  );
  const values =
    "value" in props
      ? computed(() => toValues(props.value, undefined, min.value))
      : valuesLocal;
  const set = (next: number[]) => {
    if (!("value" in props)) valuesLocal.value = next;
  };

  const primary = computed(() => values.value[0] ?? min.value);
  const percent = computed(
    () =>
      ((primary.value - min.value) / (max.value - min.value || 1)) * 100,
  );

  const commit = (next: number) => {
    const clamped = snapValue(next, min.value, max.value, step.value);
    if (!sameValues([clamped], values.value)) {
      set([clamped]);
    }
    props.onValueChange?.([clamped]);
  };

  return { min, max, step, orientation, values, primary, percent, commit };
}
